def solve(points):
    n = len(points)
    if n <= 2:
        return list(range(n))

    px = [p[0] for p in points]
    py = [p[1] for p in points]

    dist = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i):
            d = math.hypot(px[i] - px[j], py[i] - py[j])
            dist[i][j] = dist[j][i] = d

    def tour_length(t):
        return sum(dist[t[i]][t[(i + 1) % n]] for i in range(n))

    # Geometric candidate lists, augmented with angularly diverse neighbors.
    k = min(n - 1, 20 if n >= 60 else 28)
    near = []
    near_sets = []
    for i in range(n):
        order = sorted(
            (j for j in range(n) if j != i),
            key=lambda j: (dist[i][j], j)
        )
        near.append(order[:k])
        near_sets.append(set(order[:k]))

    def make_pos(t):
        pos = [0] * n
        for i, v in enumerate(t):
            pos[v] = i
        return pos

    def two_opt(tour, candidate=True, max_passes=50):
        t = tour[:]
        pos = make_pos(t)
        for _ in range(max_passes):
            changed = False
            for i in range(n):
                a = t[i]
                b = t[(i + 1) % n]
                if candidate:
                    cs = near[a]
                else:
                    cs = range(n)
                for c in cs:
                    j = pos[c]
                    if j <= i + 1 or (i == 0 and j == n - 1):
                        continue
                    d = t[(j + 1) % n]
                    if dist[a][c] + dist[b][d] >= (
                        dist[a][b] + dist[c][d] - 1e-12
                    ):
                        continue
                    t[i + 1:j + 1] = reversed(t[i + 1:j + 1])
                    for q in range(i + 1, j + 1):
                        pos[t[q]] = q
                    changed = True
                    break
                if changed:
                    break
            if not changed:
                break
        return t

    def relocate(tour, max_passes=3, block_sizes=(1,)):
        t = tour[:]
        for _ in range(max_passes):
            pos = make_pos(t)
            changed = False
            for size in block_sizes:
                if size >= n - 2:
                    continue
                for i in range(n):
                    if i + size >= n:
                        continue
                    block = t[i:i + size]
                    if not block:
                        continue
                    a = t[(i - 1) % n]
                    z = t[i + size - 1]
                    b = t[(i + size) % n]
                    removed = dist[a][b]
                    removed -= dist[a][block[0]] + dist[z][b]
                    if size > 1:
                        for q in range(size - 1):
                            removed += dist[block[q]][block[q + 1]]
                    for v in block:
                        for c in near[v]:
                            j = pos[c]
                            if i <= j < i + size:
                                continue
                            u = t[(j - 1) % n]
                            w = t[j]
                            # Insert the block before c, after removal.
                            delta = (
                                dist[a][b]
                                + dist[u][block[0]]
                                + dist[block[-1]][w]
                                - dist[a][block[0]]
                                - dist[block[-1]][b]
                                - dist[u][w]
                            )
                            if size > 1:
                                delta += sum(
                                    dist[block[q]][block[q + 1]]
                                    for q in range(size - 1)
                                )
                            if delta >= -1e-12:
                                continue
                            old = t[:]
                            del t[i:i + size]
                            jj = t.index(c)
                            t[jj:jj] = block
                            changed = True
                            break
                        if changed:
                            break
                    if changed:
                        break
                if changed:
                    break
            if not changed:
                break
        return t

